// Promedio SIMPLE (no ponderado por créditos — Canvas no expone esa
// información de forma genérica) de la nota actual de cada curso activo.
// Solo notifica si algo cambió desde la última corrida (comparando contra
// el snapshot guardado en n8n workflow static data); si no cambió nada,
// devuelve un array vacío y el nodo de email no se ejecuta.
//
// Si quieres ponderar por créditos de verdad, agrega los créditos de cada
// curso a mano en un objeto aquí (ej. { 101: 3, 102: 4 }) y ajusta el
// cálculo de `total`/`count` para usar esos pesos en vez de contar 1 por curso.

const courses = $input.all().map(i => i.json);
const staticData = $getWorkflowStaticData('global');
const previous = staticData.lastScores || {};

const current = {};
const lines = [];
let total = 0;
let count = 0;

for (const course of courses) {
  const enrollment = (course.enrollments || [])[0];
  const score = enrollment?.computed_current_score;
  if (score === null || score === undefined) continue;

  current[course.id] = score;
  total += score;
  count += 1;
  lines.push(`- ${course.name}: ${score}`);
}

const changed = JSON.stringify(current) !== JSON.stringify(previous);
staticData.lastScores = current;

if (!changed || count === 0) {
  return [];
}

const average = (total / count).toFixed(1);
const text = `Promedio simple actual: ${average}\n\n${lines.join('\n')}`;

return [{ json: { subject: 'Canvas: notas actualizadas', text } }];
